const contacts = $input.all().map(item => item.json);

const sorted = [...contacts].sort((a, b) =>
  parseInt(a.properties.createdate.value) - parseInt(b.properties.createdate.value)
);

const primaryContact = {
  firstName: sorted[0].properties.firstname?.value || '',
  lastName: sorted[0].properties.lastname?.value || '',
  email: sorted[0].properties.email?.value || ''
};

const teamContacts = sorted.slice(1).map(c => ({
  firstName: c.properties.firstname?.value || '',
  lastName: c.properties.lastname?.value || '',
  email: c.properties.email?.value || ''
}));

const allContacts = sorted.map(c => ({
  firstName: c.properties.firstname?.value || '',
  lastName: c.properties.lastname?.value || '',
  email: c.properties.email?.value || ''
}));

const companyName = sorted[0].properties.company?.value || '';
const dealName = $('Get a deal').first().json.properties.dealname?.value || '';

// Clean company name: use companyName, fall back to dealName stripped of suffixes
let cleanCompanyName = companyName;
if (!cleanCompanyName && dealName) {
  cleanCompanyName = dealName
    .replace(/\s*-\s*(Renewal|renewal).*$/, '')
    .replace(/\s+(Achievement Plan|Accelerator Plan|Assurance Plan|vCISO|MSSP).*$/, '')
    .trim();
}
if (!cleanCompanyName) cleanCompanyName = dealName || 'Unknown';
const rawEngagement = ($('Get a deal').first().json.properties.engagement?.value || '').trim();
const dealStage = $('Get a deal').first().json.properties.dealstage.value;
const dealId = $('Webhook').first().json.body[0].objectId;

// Pick single engagement + text
let engagement;
let engagementText;
const subscriptions = ['MSSP', 'Assurance Plan', 'vCISO'];
const parts = rawEngagement.split(';').map(p => p.trim()).filter(Boolean);

if (!rawEngagement || rawEngagement === 'Accelerator Plan') {
  engagement = rawEngagement || '';
  engagementText = 'Our engagement was completed 🎉';
} else if (parts.includes('Achievement Plan')) {
  engagement = 'Achievement Plan';
  engagementText = 'Your Achievement Plan was completed 🎉';
} else {
  const services = parts.filter(p => !subscriptions.includes(p));
  const subs = parts.filter(p => subscriptions.includes(p));

  if (services.length > 0) {
    engagement = services[0];
    engagementText = `Your ${services[0]} was completed 🎉`;
  } else if (subs.length > 0) {
    const sub = subs[0];
    engagement = sub;
    if (sub === 'MSSP') {
      engagementText = 'Your subscription just ended';
    } else if (sub === 'Assurance Plan') {
      engagementText = 'Your Assurance Plan just ended';
    } else if (sub === 'vCISO') {
      engagementText = 'Your vCISO just ended';
    }
  } else {
    engagement = parts[0];
    engagementText = `Your ${parts[0]} was completed 🎉`;
  }
}

return [{
  json: {
    primaryContact,
    teamContacts,
    allContacts,
    companyName,
    cleanCompanyName,
    engagement,
    engagementText,
    dealStage,
    dealId
  }
}];

